public class ThreadExecutionDemo {
    public static void main(String[] args) {
        Runnable task = () -> {
            System.out.println("Running on thread: " + Thread.currentThread().getName());
        };

        Thread worker = new Thread(task, "Worker-Thread");

        // CORRECT: Spawns a new OS thread and executes asynchronously
        worker.start();

        // INCORRECT: Executes synchronously on the 'main' thread!
        // worker.run();
    }
}
